template <typename Derived>
class PricerBase {
public:
    double price() const {
        // Resolved at COMPILE TIME: Derived is the template parameter,
        // so this cast and the call below involve no vtable, no runtime lookup.
        return static_cast<const Derived*>(this)->priceImpl();
    }
};

class EuropeanOptionPricer : public PricerBase<EuropeanOptionPricer> {
public:
    EuropeanOptionPricer(double spot, double strike, double vol, double t)
        : spot_(spot), strike_(strike), vol_(vol), t_(t) {}

    double priceImpl() const {
        // real Black-Scholes logic would go here
        double d1 = (std::log(spot_ / strike_) + 0.5 * vol_ * vol_ * t_) / (vol_ * std::sqrt(t_));
        return spot_ * 0.5 * std::erfc(-d1 / std::sqrt(2.0));  // simplified illustration
    }
private:
    double spot_, strike_, vol_, t_;
};

// Usage: europeanPricer.price() inlines directly to EuropeanOptionPricer::priceImpl()
EuropeanOptionPricer europeanPricer(100.0, 105.0, 0.2, 1.0);
double p = europeanPricer.price();

class OrderPool {
public:
    explicit OrderPool(size_t capacity) : pool_(capacity) {
        for (size_t i = 0; i < capacity; ++i) freeList_.push_back(&pool_[i]);
    }

    Order* acquire() {
        if (freeList_.empty()) throw std::bad_alloc();  // pool exhausted -- sized wrong
        Order* slot = freeList_.back();
        freeList_.pop_back();
        return slot;
    }

    void release(Order* order) {
        freeList_.push_back(order);   // no deallocation -- just back on the free list
    }

private:
    std::vector<Order> pool_;         // one contiguous block, allocated once up front
    std::vector<Order*> freeList_;    // available slots -- O(1) push/pop
};

// Usage: no general-purpose new/delete call on the hot path
OrderPool pool(100000);
Order* o = pool.acquire();
// ... use o ...
pool.release(o);

std::atomic<Node*> head{nullptr};
thread_local std::atomic<Node*> hazardPointer{nullptr};  // one per thread, published globally

Node* pop() {
    Node* node;
    while (true) {
        node = head.load(std::memory_order_acquire);
        if (!node) return nullptr;
        hazardPointer.store(node, std::memory_order_release);   // publish: "I'm examining this"
        // Re-check head hasn't changed since we published -- avoids a race on the read itself
        if (head.load(std::memory_order_acquire) != node) continue;

        Node* next = node->next;   // safe to read: our hazard pointer protects 'node' from being freed
        if (head.compare_exchange_weak(node, next, std::memory_order_acq_rel)) {
            break;  // successfully popped 'node'
        }
    }
    hazardPointer.store(nullptr, std::memory_order_release);
    return node;
}

void retireNode(Node* node) {
    // Before actually freeing: check every thread's hazard pointer slot.
    // If any thread's hazard pointer == node, defer the free (e.g. push to a retire list)
    // instead of deleting it immediately.
    if (!anyThreadHazardPointerEquals(node)) delete node;
    else addToRetireList(node);
}

struct TaggedPtr {
    Node* ptr;
    uint64_t tag;   // increments on every successful CAS touching this slot
};
std::atomic<TaggedPtr> head;   // requires double-width (e.g. 128-bit) atomic CAS support

void push(Node* node) {
    TaggedPtr oldHead, newHead;
    do {
        oldHead = head.load(std::memory_order_relaxed);
        node->next = oldHead.ptr;
        newHead = {node, oldHead.tag + 1};   // tag bumps on every attempt
    } while (!head.compare_exchange_weak(oldHead, newHead,
                                          std::memory_order_acq_rel));
}

Node* pop() {
    TaggedPtr oldHead, newHead;
    do {
        oldHead = head.load(std::memory_order_acquire);
        if (!oldHead.ptr) return nullptr;
        newHead = {oldHead.ptr->next, oldHead.tag + 1};
        // Even if 'oldHead.ptr' address gets reused by another thread's push/pop
        // during this loop, the tag will no longer match -- CAS correctly fails below.
    } while (!head.compare_exchange_weak(oldHead, newHead,
                                          std::memory_order_acq_rel));
    return oldHead.ptr;
}
